// Send gate for the assistant's push notifications.
// Promo policy: at most 3 per customer per local calendar day (customer's time zone),
// and at least 2 hours between two promos to the same customer.
// Security alerts are never limited and never counted against the promo limits.

const MAX_PROMOS_PER_DAY = 3;
const MIN_GAP_MS = 2 * 60 * 60 * 1000;
const KEEP_MS = 48 * 60 * 60 * 1000; // older promos can no longer affect the day or gap checks

const formatters = new Map();

function dayFormatter(timeZone) {
  let f = formatters.get(timeZone);
  if (!f) {
    f = new Intl.DateTimeFormat("en-CA", {
      timeZone,
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
    });
    formatters.set(timeZone, f);
  }
  return f;
}

// Local calendar day ("YYYY-MM-DD") of a timestamp in the given zone. Throws RangeError on a bad zone.
function localDay(ms, timeZone) {
  const parts = dayFormatter(timeZone).formatToParts(new Date(ms));
  let y = "", m = "", d = "";
  for (const p of parts) {
    if (p.type === "year") y = p.value;
    else if (p.type === "month") m = p.value;
    else if (p.type === "day") d = p.value;
  }
  return `${y}-${m}-${d}`;
}

export function createGate() {
  // userId -> array of { id, at } for promos that were allowed and not cancelled
  const promos = new Map();
  // id -> userId, so cancel can find the record
  const owners = new Map();
  let counter = 0;

  function deny(rule) {
    return { allowed: false, rule, id: null };
  }

  function nextId() {
    counter += 1;
    return `push-${counter}`;
  }

  function request({ userId, timeZone, category, now } = {}) {
    if (category === "security") {
      return { allowed: true, rule: "", id: nextId() };
    }
    if (category !== "promo") return deny("unknown-category");

    const at = now instanceof Date ? now.getTime() : NaN;
    if (!Number.isFinite(at)) return deny("invalid-time");

    let today;
    try {
      today = localDay(at, timeZone);
    } catch {
      return deny("invalid-time-zone");
    }

    let list = promos.get(userId);
    if (list) {
      const kept = [];
      for (const p of list) {
        if (p.at >= at - KEEP_MS) kept.push(p);
        else owners.delete(p.id);
      }
      list = kept;
      promos.set(userId, list);
    } else {
      list = [];
      promos.set(userId, list);
    }

    let todayCount = 0;
    let tooClose = false;
    for (const p of list) {
      if (localDay(p.at, timeZone) === today) todayCount += 1;
      if (Math.abs(at - p.at) < MIN_GAP_MS) tooClose = true;
    }

    if (todayCount >= MAX_PROMOS_PER_DAY) return deny("daily-cap");
    if (tooClose) return deny("min-gap");

    // Allowed means the caller sends immediately, so record it now.
    const id = nextId();
    list.push({ id, at });
    owners.set(id, userId);
    return { allowed: true, rule: "", id };
  }

  function cancel(id) {
    const userId = owners.get(id);
    if (userId === undefined) return;
    owners.delete(id);
    const list = promos.get(userId);
    if (!list) return;
    const i = list.findIndex((p) => p.id === id);
    if (i >= 0) list.splice(i, 1);
  }

  return { request, cancel };
}

import assert from "node:assert/strict";
import { createGate } from "<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round8-final/d-sonnet/work/knock-d2-1/bot.mjs";

const LA = "America/Los_Angeles";
const at = (s) => new Date(s);
const req = (g, o) => g.request({ userId: "u", timeZone: LA, category: "promo", ...o });

// cap of 3 per local day; LA is UTC-7 in October (PDT)
let g = createGate();
assert.equal(req(g, { now: at("2026-10-20T07:00:00Z") }).allowed, true); // 00:00 local
assert.equal(req(g, { now: at("2026-10-20T09:00:00Z") }).allowed, true);
const third = req(g, { now: at("2026-10-20T11:00:00Z") });
assert.equal(third.allowed, true);
const r4 = req(g, { now: at("2026-10-20T13:00:00Z") });
assert.deepEqual(r4, { allowed: false, rule: "daily-cap", id: null });
// next local midnight = 07:00Z next day
assert.equal(req(g, { now: at("2026-10-21T06:59:00Z") }).rule, "daily-cap");
assert.equal(req(g, { now: at("2026-10-21T07:00:00Z") }).allowed, true);

// gap: exactly 2h ok, 1h59 not
g = createGate();
assert.equal(req(g, { now: at("2026-10-20T15:00:00Z") }).allowed, true);
assert.equal(req(g, { now: at("2026-10-20T16:59:00Z") }).rule, "min-gap");
assert.equal(req(g, { now: at("2026-10-20T17:00:00Z") }).allowed, true);

// same instant, different zones -> different days
g = createGate();
for (const h of ["10", "12", "14"]) assert.ok(g.request({ userId: "u", timeZone: "Europe/Berlin", category: "promo", now: at(`2026-10-20T${h}:00:00Z`) }).allowed);
assert.equal(g.request({ userId: "u", timeZone: "Europe/Berlin", category: "promo", now: at("2026-10-20T22:30:00Z") }).rule, "daily-cap");
assert.ok(g.request({ userId: "u", timeZone: "Europe/Berlin", category: "promo", now: at("2026-10-20T22:30:00Z") }).rule);
assert.ok(g.request({ userId: "u", timeZone: "Europe/Berlin", category: "promo", now: at("2026-10-20T23:30:00Z") }).allowed); // Berlin 01:30 next day

// users independent
g = createGate();
assert.ok(req(g, { now: at("2026-10-20T15:00:00Z") }).allowed);
assert.ok(g.request({ userId: "v", timeZone: LA, category: "promo", now: at("2026-10-20T15:00:00Z") }).allowed);

// security unlimited and uncounted
g = createGate();
for (let i = 0; i < 10; i++) assert.ok(g.request({ userId: "u", timeZone: LA, category: "security", now: at("2026-10-20T15:00:00Z") }).allowed);
assert.ok(req(g, { now: at("2026-10-20T15:00:00Z") }).allowed);

// cancel frees the slot and the gap
g = createGate();
const a = req(g, { now: at("2026-10-20T15:00:00Z") });
assert.equal(req(g, { now: at("2026-10-20T15:30:00Z") }).rule, "min-gap");
g.cancel(a.id);
g.cancel(a.id); g.cancel("nope");
assert.ok(req(g, { now: at("2026-10-20T15:30:00Z") }).allowed);

// cancel reduces the daily count
g = createGate();
const ids = [0, 2, 4].map((h) => req(g, { now: at(`2026-10-20T${15 + h}:00:00Z`) }));
assert.equal(req(g, { now: at("2026-10-20T21:00:00Z") }).rule, "daily-cap");
g.cancel(ids[1].id);
assert.ok(req(g, { now: at("2026-10-20T21:00:00Z") }).allowed);

// DST day (Europe/Berlin 2026-10-25 is 25h long): local-day logic still correct
g = createGate();
assert.ok(g.request({ userId: "u", timeZone: "Europe/Berlin", category: "promo", now: at("2026-10-24T22:00:00Z") }).allowed); // 00:00 CEST Oct 25
assert.ok(g.request({ userId: "u", timeZone: "Europe/Berlin", category: "promo", now: at("2026-10-25T00:00:00Z") }).allowed);
assert.ok(g.request({ userId: "u", timeZone: "Europe/Berlin", category: "promo", now: at("2026-10-25T02:00:00Z") }).allowed);
assert.equal(g.request({ userId: "u", timeZone: "Europe/Berlin", category: "promo", now: at("2026-10-25T23:00:00Z") }).rule, "daily-cap"); // 00:00 CET Oct 26? no: 23:00Z = 00:00 CET Oct 26
console.log("unreachable-check");

